-- Généré par scripts/generate_cities_migration.py depuis GeoNames cities5000.txt (69802 villes, licence CC BY 4.0, https://www.geonames.org).
-- Destinations d'hébergement : autocomplétion (`search_names`) et coordonnées envoyées à Duffel Stays.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE city
(
    id           INTEGER PRIMARY KEY,
    name         TEXT             NOT NULL,
    country_code CHAR(2)          NOT NULL,
    latitude     DOUBLE PRECISION NOT NULL,
    longitude    DOUBLE PRECISION NOT NULL,
    population   BIGINT           NOT NULL,
    timezone     TEXT             NOT NULL,
    -- Nom principal normalisé (sans accents, minuscules) : classe les correspondances exactes en tête.
    name_key     TEXT             NOT NULL,
    -- Tous les noms normalisés, « | » entre eux, précédés d'une espace.
    search_names TEXT             NOT NULL
);


CREATE INDEX city_search_names_trgm_idx ON city USING GIN (search_names gin_trgm_ops);
CREATE INDEX city_name_key_idx ON city (name_key text_pattern_ops);
